WITH filtered AS (SELECT id, order_id, paid_at, status, COALESCE(amount, 0) AS amount_filled FROM payments WHERE method IS DISTINCT FROM 'card'), gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM filtered), sessions_payments AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps), latest AS (SELECT *, RANK() OVER (PARTITION BY status, order_id ORDER BY paid_at DESC NULLS LAST) AS dedup_rank FROM sessions_payments QUALIFY dedup_rank = 1), ranked AS (SELECT * FROM latest QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY burst_id, id) = 1), with_dims AS (SELECT s.id, s.order_id, s.new_group_flag, o.discount FROM ranked s INNER JOIN orders o ON s.order_id = o.id WHERE o.store_id IN (15, 20, 33, 34)), enriched AS (SELECT a.id, a.order_id, a.new_group_flag, a.discount, p.amount, p.channel FROM with_dims a INNER JOIN orders p ON a.order_id = p.id), ranked_payments AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY discount DESC NULLS LAST, id) AS row_num FROM enriched) x WHERE row_num = 1) SELECT CASE WHEN amount >= 1790 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, CASE WHEN discount >= 0.31 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_tier, order_id, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN channel = 'web' THEN 1 END), 0), 2) AS amount_per_web, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, COUNT(DISTINCT channel) AS distinct_channels, SIZE(COLLECT_SET(channel)) AS num_channels, COUNT(CASE WHEN channel = 'store' THEN 1 END) AS store_count, COUNT(*) AS row_count FROM ranked_payments GROUP BY CASE WHEN amount >= 1790 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN discount >= 0.31 THEN 'PREMIUM' ELSE 'STANDARD' END, order_id ORDER BY order_id;
